), ins AS (
INSERT INTO public.properties (owner_id,name,name_hy,name_ru,name_en,slug,description,description_hy,description_en,property_type,city_code,region_code,price_per_night,max_guests,bedrooms,beds,bathrooms,status,is_active,is_demo,main_image_url,rating,approved_at,submitted_at)
SELECT '8401f09d-e58f-4f07-8c3d-77a1bb7b3de5',name,name,name_ru,name_en,slug,descr,descr,name_en,ptype,city,region,price,guests,beds,beds+1,greatest(1,beds-1),'APPROVED',true,true,img,4.7,now(),now() FROM d
ON CONFLICT (slug) DO NOTHING
RETURNING id,slug,main_image_url,price_per_night)
, im AS (INSERT INTO public.property_images (property_id,image_url,sort_order,is_cover) SELECT id,main_image_url,0,true FROM ins)
, pr AS (INSERT INTO public.property_pricing (property_id,pricing_type,fixed_price) SELECT id,'FIXED',price_per_night FROM ins)
INSERT INTO public.property_amenities (property_id,amenity_code)
SELECT ins.id, unnest(d.am::text[]) FROM ins JOIN d ON d.slug=ins.slug;